MATLAB.Graphics.FigureAspectRatio(8,5,MATLAB.Flags.Narrow); %[output:5e48b03c]
title(Layout,'Ensemble Final') %[output:5e48b03c]
print(Fig,TransferLearning.ProjectPath('Fig2E.svg'),'-dsvg'); %[output:5e48b03c]
%%
%[text] ## F
Fig=figure; %[output:5b410a5f]
Layout=tiledlayout(1,2,TileSpacing='tight',Padding='compact'); %[output:5b410a5f]
EnsembleFLT=UniExp.NtatsCellStrip(rmfield(EnsembleEF,'Final'));
EnsembleFLT=EnsembleFLT(max(EnsembleFLT.NTATS.Learned(:,25:32),[],2)>std(EnsembleFLT.NTATS.Learned(:,1:24),[],2)*3,:);
EnsembleFLT.NTATS=EnsembleFLT.NTATS.Transfer;
EnsembleFLT.Phase(:)="Transfer";
EnsembleFLT.Response=max(EnsembleFLT.NTATS(:,25:32),[],2);
EnsembleFF=EnsembleEF.Final;
EnsembleFF.Response=max(EnsembleFF.NTATS(:,25:32),[],2);
EnsembleFF=EnsembleFF(EnsembleFF.Response>std(EnsembleFF.NTATS(:,1:24),[],2)*3,:);
EnsembleFF.Phase(:)="Final";
EnsembleF=[EnsembleFLT;EnsembleFF];
[~,RisingTime]=max(diff(EnsembleF.NTATS(:,25:end),1,2),[],2);
EnsembleF.RisingTime=RisingTime*milliseconds(125);
[~,Index]=ismember(EnsembleF.CellUID,ALB.Cells.CellUID);
EnsembleF.ZLayer=ALB.Cells.ZLayer(Index);
TimeComparison=UniExp.TabularAnovaN(EnsembleF.RisingTime,EnsembleF(:,["Phase","ZLayer"]),Comparison=table(["Transfer","Final";"Transfer","Final"],["MOp2/3","MOp2/3";"MOp5","MOp5"],'VariableNames',["Phase","ZLayer"]),Model=2,Display=false);
BarData=groupsummary(EnsembleF,["Phase","ZLayer"],["mean","std"],"RisingTime");
BarData.SEM=BarData.std_RisingTime./sqrt(BarData.GroupCount);
nexttile; %[output:5b410a5f]
Bars=bar(reshape(BarData.mean_RisingTime,2,2)); %[output:5b410a5f]
hold on; %[output:5b410a5f]
errorbar([Bars.XEndPoints],[Bars.YEndPoints],[],BarData.SEM,'k',LineWidth=2,LineStyle='none'); %[output:5b410a5f]
PX=vertcat(Bars.XEndPoints);
YLim=ylim;
LevelStep=YLim(2)/10;
PY=max(reshape(BarData.mean_RisingTime+BarData.SEM,2,2),[],2).'+LevelStep;
PY=[PY;PY];
line(PX,PY,Color='k'); %[output:5b410a5f]
PY=PY(1,:)+LevelStep;
text(1:2,PY,"*",HorizontalAlignment='center',VerticalAlignment='top',AffectAutoLimits=true); %[output:5b410a5f]
colororder([1,0,1;0,0.5,0]); %[output:5b410a5f]
YLim=ylim;
ylim([0,YLim(2)]); %[output:5b410a5f]
xticklabels(["Layer 2","Layer 5"]); %[output:5b410a5f]
ylabel('Rising time'); %[output:5b410a5f]
%[text] 峰值统计
ResponseComparison=UniExp.TabularAnovaN(EnsembleF.Response,EnsembleF(:,["Phase","ZLayer"]),Comparison=table(["Transfer","Final";"Transfer","Final"],["MOp2/3","MOp2/3";"MOp5","MOp5"],'VariableNames',["Phase","ZLayer"]),Model=2,Display=false);
BarData=groupsummary(EnsembleF,["Phase","ZLayer"],["mean","std"],"Response");
BarData.SEM=BarData.std_Response./sqrt(BarData.GroupCount);
nexttile; %[output:5b410a5f]
Bars=bar(reshape(BarData.mean_Response,2,2)); %[output:5b410a5f]
hold on; %[output:5b410a5f]
errorbar([Bars.XEndPoints],[Bars.YEndPoints],[],BarData.SEM,'k',LineWidth=2,LineStyle='none'); %[output:5b410a5f]
PX=vertcat(Bars.XEndPoints);
YLim=ylim;
LevelStep=YLim(2)/10;
PY=max(reshape(BarData.mean_Response+BarData.SEM,2,2),[],2).'+LevelStep;
PY=[PY;PY];
line(PX,PY,Color='k'); %[output:5b410a5f]
text(1:2,PY(1,:)+LevelStep,"*",HorizontalAlignment='center',VerticalAlignment='top',AffectAutoLimits=true); %[output:5b410a5f]
colororder([1,0,1;0,0.5,0]); %[output:5b410a5f]
YLim=ylim;
ylim([0,YLim(2)]); %[output:5b410a5f]
xticklabels(["Layer 2","Layer 5"]); %[output:5b410a5f]
ylabel('Max z-score in 1s'); %[output:5b410a5f]
L=legend(Bars,unique(BarData.Phase)); %[output:5b410a5f]
MATLAB.Graphics.FigureAspectRatio(8,5,MATLAB.Flags.Narrow); %[output:5b410a5f]
print(Fig,TransferLearning.ProjectPath('Fig2F.svg'),'-dsvg'); %[output:5b410a5f]
%%
%[text] # （备用）
%[text] 相关性亚群
EnsembleE=EnsembleCD.Learned;
EnsembleE=EnsembleE(max(EnsembleE.NTATS(:,25:32),[],2)>std(EnsembleE.NTATS(:,1:24),[],2)*3,:);
Normalized=normalize(EnsembleE.NTATS,2,'zscore');
Correlation=corrcoef(Normalized.');
SortIndex=UniExp.CorrelationSort(Correlation);
Correlation(SortIndex,SortIndex)=Correlation;
Fig=figure;
imagesc(Correlation);
CB=colorbar;
CB.Label.String='Correlation';
colormap(gray);
title('Layer 2');
axis off;
MATLAB.Graphics.FigureAspectRatio(8,5,MATLAB.Flags.Narrow);
print(Fig,TransferLearning.ProjectPath('Fig2E.svg'),'-dsvg');
%[text] 与光水Naive比较
Fig=figure;
Layout=tiledlayout(1,2,TileSpacing='tight',Padding='compact');

%%
%[text] 与光水Naive比较
EnsembleF2=LAB.QueryNTATS(struct(Stimulus="LightWater",Phase="Naive"),UniExp.Flags.ZScore,1:24,UniExp.Flags.Median);
%%
EnsembleF2=EnsembleF2(max(EnsembleF2.NTATS{:,25:32},[],2)>std(EnsembleF2.NTATS{:,1:24},[],2)*3,:);
[~,Index]=ismember(EnsembleF2.CellUID,LAB.Cells.CellUID);
EnsembleF2.ZLayer=LAB.Cells.ZLayer(Index);
EnsembleF2.Phase(:)="Naive";
%%
[~,RisingTime]=max(diff(EnsembleF2.NTATS{:,25:end},1,2),[],2);
EnsembleF2.RisingTime=RisingTime*milliseconds(125);
EnsembleF2.Response=max(EnsembleF2.NTATS{:,25:32},[],2);
AnovaTable(AnovaTable.Phase=="Learned",:)=[];
%%
EnsembleF2.NTATS=EnsembleF2.NTATS.Data;
%%
AnovaTable=[AnovaTable;EnsembleF2(:,["NTATS","Phase","ZLayer","RisingTime","Response"])];
%%
TimeComparison=UniExp.TabularAnovaN(AnovaTable.RisingTime,AnovaTable(:,["Phase","ZLayer"]),Comparison=table(["Naive","Transfer";"Naive","Transfer"],["MOp2/3","MOp2/3";"MOp5","MOp5"],'VariableNames',["Phase","ZLayer"]),Model=2,Display=false);
%%
BarData=groupsummary(AnovaTable,["Phase","ZLayer"],["mean","std"],"RisingTime");
BarData.SEM=BarData.std_RisingTime./sqrt(BarData.GroupCount);
%%
nexttile;
Bars=bar(reshape(BarData.mean_RisingTime,2,2));
hold on;
errorbar([Bars.XEndPoints],[Bars.YEndPoints],[],BarData.SEM,'k',LineWidth=2,LineStyle='none');
PX=vertcat(Bars.XEndPoints);
YLim=ylim;
LevelStep=YLim(2)/6;
PY=max(reshape(BarData.mean_RisingTime+BarData.SEM,2,2),[],2).'+LevelStep;
PY=[PY;PY];
line(PX,PY,Color='k');
PY=PY(1,:)+LevelStep;
text(1:2,PY,"p="+MATLAB.SignificantFixedpoint(ResponseComparison.PValue(1:2),2),HorizontalAlignment='center',VerticalAlignment='top',AffectAutoLimits=true);
colororder([1,0,1;0,0.5,0]);
YLim=ylim;
ylim([0,YLim(2)]);
xticklabels(["Layer 2","Layer 5"]);
ylabel('Rising time');
legend(Bars,unique(BarData.Phase),Location='southeast');
%%
%[text] 峰值统计
ResponseComparison=UniExp.TabularAnovaN(AnovaTable.Response,AnovaTable(:,["Phase","ZLayer"]),Comparison=table(["Naive","Transfer";"Naive","Transfer"],["MOp2/3","MOp2/3";"MOp5","MOp5"],'VariableNames',["Phase","ZLayer"]),Model=2,Display=false);
BarData=groupsummary(AnovaTable,["Phase","ZLayer"],["mean","std"],"Response");
BarData.SEM=BarData.std_Response./sqrt(BarData.GroupCount);
nexttile;
Bars=bar(reshape(BarData.mean_Response,2,2));
hold on;
errorbar([Bars.XEndPoints],[Bars.YEndPoints],[],BarData.SEM,'k',LineWidth=2,LineStyle='none');
PX=vertcat(Bars.XEndPoints);
YLim=ylim;
LevelStep=YLim(2)/6;
PY=max(reshape(BarData.mean_Response+BarData.SEM,2,2),[],2).'+LevelStep;
PY=[PY;PY];
line(PX,PY,Color='k');
text(1:2,PY(1,:)+LevelStep,"p="+MATLAB.SignificantFixedpoint(ResponseComparison.PValue(1:2),2),HorizontalAlignment='center',VerticalAlignment='top',AffectAutoLimits=true);
colororder([1,0,1;0,0.5,0]);
YLim=ylim;
ylim([0,YLim(2)]);
xticklabels(["Layer 2","Layer 5"]);
ylabel('Max z-score in 1s');
%%


